(1577837, 211760, 15711, '<td valign="top">Love the title.  This is nice - good rich tones and clarity. Upon 2nd review, I''m upping this to an 8. The total clarity and the single movement of the figure makes for quite an interesting shot.</td>', 'Love the title.  This is nice - good rich tones and clarity. Upon 2nd review, I''m upping this to an 8. The total clarity and the single movement of the figure makes for quite an interesting shot.', '2005-08-01 10:12:40.000000', NULL, 1),
(1577840, 211559, 15711, '<td valign="top">I love the blue of the lights.  The crop seems a tad tight, but maybe that was intentional. It certainly leads your eye up with the perspective you chose.</td>', 'I love the blue of the lights.  The crop seems a tad tight, but maybe that was intentional. It certainly leads your eye up with the perspective you chose.', '2005-08-01 10:13:31.000000', NULL, 1),
