(1578694, 210726, 18080, '<td valign="top">GREAT shot.<br/>I love the idea and this is well taken<br/>10<br/>good luck</td>', 'GREAT shot.I love the idea and this is well taken10good luck', '2005-08-01 17:24:05.000000', NULL, 1),
(1578695, 211466, 3087, '<td valign="top">Like how his face and expression are so clear even though there''s still clear motion. Very emotive.</td>', 'Like how his face and expression are so clear even though there''s still clear motion. Very emotive.', '2005-08-01 17:24:26.000000', NULL, 1),
(1578696, 211214, 19095, '<td valign="top">Way too confusing for  me - don''t know what I am looking at or what to look for!</td>', 'Way too confusing for  me - don''t know what I am looking at or what to look for!', '2005-08-01 17:24:46.000000', NULL, 1),
(1578697, 210837, 3087, '<td valign="top">Strangely sci-fi in feel, almost sinistre in mood. Minimal works well here.</td>', 'Strangely sci-fi in feel, almost sinistre in mood. Minimal works well here.', '2005-08-01 17:24:55.000000', NULL, 1),
(1578698, 211733, 19095, '<td valign="top">Love it - one of the better pics here.</td>', 'Love it - one of the better pics here.', '2005-08-01 17:25:02.000000', NULL, 1),
(1578699, 211896, 3087, '<td valign="top">Oooh, Healthcliffe, it''s Kathy, I''ve come home now... let me into your window. VERY moody, very evocative, excellent composition, perfect choice of dress, nice detail in grass and sky. Wonderful!</td>', 'Oooh, Healthcliffe, it''s Kathy, I''ve come home now... let me into your window. VERY moody, very evocative, excellent composition, perfect choice of dress, nice detail in grass and sky. Wonderful!', '2005-08-01 17:25:43.000000', NULL, 1),
(1578700, 211771, 19095, '<td valign="top">What is the crack doing there - doesn''t add anything, only distracts!</td>', 'What is the crack doing there - doesn''t add anything, only distracts!', '2005-08-01 17:25:44.000000', NULL, 1),
(1578701, 210816, 19095, '<td valign="top">Nice - well framed.</td>', 'Nice - well framed.', '2005-08-01 17:26:07.000000', NULL, 1),
(1578703, 211475, 3087, '<td valign="top">Lovely abstract anchored by the shape of the white flower shaped centres of the larger flowers.</td>', 'Lovely abstract anchored by the shape of the white flower shaped centres of the larger flowers.', '2005-08-01 17:26:56.000000', NULL, 1),
(1578705, 211787, 19095, '<td valign="top">Nice picture but I am sorry to say that it has nothing that stands out - a nice waterfall but....</td>', 'Nice picture but I am sorry to say that it has nothing that stands out - a nice waterfall but....', '2005-08-01 17:27:02.000000', NULL, 1),
(1578707, 210973, 3087, '<td valign="top">Spooky, sinistre, mysterious, intriguing - i.e. this one conveys a whole heap of potential scenarious and moods. Nice colours and textures too.</td>', 'Spooky, sinistre, mysterious, intriguing - i.e. this one conveys a whole heap of potential scenarious and moods. Nice colours and textures too.', '2005-08-01 17:27:51.000000', NULL, 1),
(1578709, 210448, 19095, '<td valign="top">Mixed feelings here - a bit to scary but still good, maybe less wall and moore of the girl?</td>', 'Mixed feelings here - a bit to scary but still good, maybe less wall and moore of the girl?', '2005-08-01 17:28:09.000000', NULL, 1),
(1578712, 211894, 19095, '<td valign="top">This might have worked if you had panned , but a moved person and moved background is had to make interesting.</td>', 'This might have worked if you had panned , but a moved person and moved background is had to make interesting.', '2005-08-01 17:29:31.000000', NULL, 1),
(1578713, 210425, 3087, '<td valign="top">What an incredible image. This should be hanging in a gallery in London or New York. The emotions are so strong within it that I can hardly tear myself away from it to write about it, let alone express what it''s making me feel. I like that th main texture, the main thing that''s solid is a weathered piece of wood and this unnoticed girl is a shadow behind it. Black and white perfect for it. Shame about the blown highlights to the right of the bar but doesn''t stop it from being a 10.</td>', 'What an incredible image. This should be hanging in a gallery in London or New York. The emotions are so strong within it that I can hardly tear myself away from it to write about it, let alone express what it''s making me feel. I like that th main texture, the main thing that''s solid is a weathered piece of wood and this unnoticed girl is a shadow behind it. Black and white perfect for it. Shame about the blown highlights to the right of the bar but doesn''t stop it from being a 10.', '2005-08-01 17:29:33.000000', NULL, 1),
(1578714, 210764, 19095, '<td valign="top">This one has a dreamy effect.</td>', 'This one has a dreamy effect.', '2005-08-01 17:29:56.000000', NULL, 1),
(1578715, 211793, 34659, '<td valign="top">Beautiful shot.  Love the border too.  Perfect lighting and composition.  VERY well done.</td>', 'Beautiful shot.  Love the border too.  Perfect lighting and composition.  VERY well done.', '2005-08-01 17:30:15.000000', NULL, 1),
(1578716, 211697, 19095, '<td valign="top">The long exposure adds nothing to this scene, sorry!</td>', 'The long exposure adds nothing to this scene, sorry!', '2005-08-01 17:30:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1578719, 209838, 19095, '<td valign="top">Interesting idea and it has worked out well.</td>', 'Interesting idea and it has worked out well.', '2005-08-01 17:31:10.000000', NULL, 1),
(1578723, 211858, 34659, '<td valign="top">Great shot!  Almost looks like water reflections of light dancing in the background.  Very nice color &amp; composition.  Well done!</td>', 'Great shot!  Almost looks like water reflections of light dancing in the background.  Very nice color & composition.  Well done!', '2005-08-01 17:31:59.000000', NULL, 1),
(1578724, 211733, 3087, '<td valign="top">Intriguing, especially with that sweeping zigzag below. Nice composition, unusual colours.</td>', 'Intriguing, especially with that sweeping zigzag below. Nice composition, unusual colours.', '2005-08-01 17:32:17.000000', NULL, 1),
(1578725, 210943, 19095, '<td valign="top">Sorry, I can''t say anything good about this one other then keep on practising and not all experiments work out !</td>', 'Sorry, I can''t say anything good about this one other then keep on practising and not all experiments work out !', '2005-08-01 17:32:40.000000', NULL, 1),
(1578729, 211500, 3087, '<td valign="top">Great timing in terms of making a nice skyscape into a WOW composition. Lovely series of lights from the streetlamps to the office lights to the firework itself.</td>', 'Great timing in terms of making a nice skyscape into a WOW composition. Lovely series of lights from the streetlamps to the office lights to the firework itself.', '2005-08-01 17:33:13.000000', NULL, 1),
(1578731, 210821, 31534, '<td valign="top">Beautiful, where is this magical place? Great colors and perfect focus.</td>', 'Beautiful, where is this magical place? Great colors and perfect focus.', '2005-08-01 17:33:59.000000', NULL, 1),
(1578734, 210979, 3087, '<td valign="top">Goodness that''s clever and DIFFERENT! So many cliche shots of that bridge and yet here''s something I haven''t seen before. I like how it anchors me to the foreground and the situation and yet still lets me look out over that golden detail. Great composition, great innovation.</td>', 'Goodness that''s clever and DIFFERENT! So many cliche shots of that bridge and yet here''s something I haven''t seen before. I like how it anchors me to the foreground and the situation and yet still lets me look out over that golden detail. Great composition, great innovation.', '2005-08-01 17:34:53.000000', NULL, 1),
(1578737, 209941, 3087, '<td valign="top">Nice capture with lovely muted tones and wonderful simplicity.</td>', 'Nice capture with lovely muted tones and wonderful simplicity.', '2005-08-01 17:35:18.000000', NULL, 1),
(1578750, 211896, 18080, '<td valign="top">Could this be Heida?<br/>I wonder.<br/>Wonderful shot.<br/>Just the right amount of exposure on you model before you removed her.<br/>I love it<br/>Good work<br/>If this isn''t Heida then it is a compliment.<br/>If it is then, good job (as usual)<br/> <br/>Good luck<br/> <br/>Kev</td>', 'Could this be Heida?I wonder.Wonderful shot.Just the right amount of exposure on you model before you removed her.I love itGood workIf this isn''t Heida then it is a compliment.If it is then, good job (as usual) Good luck Kev', '2005-08-01 17:39:37.000000', NULL, 1),
(1578780, 211849, 25174, '<td valign="top">Impressive, especially how you managed to keep it so centered and stable.</td>', 'Impressive, especially how you managed to keep it so centered and stable.', '2005-08-01 17:50:44.000000', NULL, 1),
(1578781, 211357, 14671, '<td valign="top">In the eye of a slinky lol.  Nice shot.  Beautiful colors, great composition and very crisp. &lt;8&gt;</td>', 'In the eye of a slinky lol.  Nice shot.  Beautiful colors, great composition and very crisp. <8>', '2005-08-01 17:51:03.000000', NULL, 1),
(1578786, 211800, 14671, '<td valign="top">The angle of this particular photo makes it hard to look at.  It appears the perspective is off or sloping.  I realy like how the subject stayed still and puts a crispness into the image.  Well done and good luck in this challenge. &lt;6&gt;</td>', 'The angle of this particular photo makes it hard to look at.  It appears the perspective is off or sloping.  I realy like how the subject stayed still and puts a crispness into the image.  Well done and good luck in this challenge. <6>', '2005-08-01 17:53:09.000000', NULL, 1),
(1578802, 211466, 14671, '<td valign="top">As interesting as this shot is I''m not fond of it.  I loks well enough like abstract which I don''t have a problem with usually but there is something about this shot that I just don''t like.  It has amazing color range and I like the way the microphone stand is in focus.  This photo looks like something I''d see on a CD cover/jacket.  It fits the challenge well and the yellow glimmer puts a almost flame like feature on the guitar.  Good luck in this challenge. &lt;6&gt;</td>', 'As interesting as this shot is I''m not fond of it.  I loks well enough like abstract which I don''t have a problem with usually but there is something about this shot that I just don''t like.  It has amazing color range and I like the way the microphone stand is in focus.  This photo looks like something I''d see on a CD cover/jacket.  It fits the challenge well and the yellow glimmer puts a almost flame like feature on the guitar.  Good luck in this challenge. <6>', '2005-08-01 18:00:49.000000', NULL, 1),
(1578805, 209188, 14671, '<td valign="top">Interesting shot.  Colors are good and clarity is fair.  Good luck in this chalenge.  &lt;5&gt;</td>', 'Interesting shot.  Colors are good and clarity is fair.  Good luck in this chalenge.  <5>', '2005-08-01 18:03:26.000000', NULL, 1),
(1578807, 211709, 36701, '<td valign="top">nice bike. how did you mount the camera? great picture</td>', 'nice bike. how did you mount the camera? great picture', '2005-08-01 18:04:35.000000', NULL, 1),
(1578808, 211828, 14671, '<td valign="top">I find it kinda hard to see how tihs fits the challenge and all in all not a shot I''d hang on a wall.  Good luck in this challenge.  &lt;5&gt;</td>', 'I find it kinda hard to see how tihs fits the challenge and all in all not a shot I''d hang on a wall.  Good luck in this challenge.  <5>', '2005-08-01 18:04:54.000000', NULL, 1),
(1578810, 211464, 36701, '<td valign="top">wow</td>', 'wow', '2005-08-01 18:06:26.000000', NULL, 1),
(1578811, 211900, 14671, '<td valign="top">The shots a little dark for my liking.  I also think if you didn''t see the driver would have made more of an impact.  Good luck in this challenge.  &lt;5&gt;</td>', 'The shots a little dark for my liking.  I also think if you didn''t see the driver would have made more of an impact.  Good luck in this challenge.  <5>', '2005-08-01 18:07:32.000000', NULL, 1),
(1578815, 208981, 14671, '<td valign="top">I wonder how this would have done in the lines challenge.  Interesting perspecive on this challenge an I really like the colors/lights going thru the screen as it draws the eyes into the photo.  Well done and good luck in this challenge.  &lt;7&gt;</td>', 'I wonder how this would have done in the lines challenge.  Interesting perspecive on this challenge an I really like the colors/lights going thru the screen as it draws the eyes into the photo.  Well done and good luck in this challenge.  <7>', '2005-08-01 18:09:17.000000', NULL, 1),
(1578818, 211783, 14671, '<td valign="top">Wow pretty cool.  Looks almost like a photoshop effect.  Nicely done.  Good luck in this chalenge.  &lt;7&gt;</td>', 'Wow pretty cool.  Looks almost like a photoshop effect.  Nicely done.  Good luck in this chalenge.  <7>', '2005-08-01 18:10:47.000000', NULL, 1),
(1578826, 211824, 14671, '<td valign="top">lol the title goes very well with this photo.  Excellent crispness and colors.  I like the greaan background with the DoF as I find it brings out more colors in the photo.  Well done and good luck in this challenge.  &lt;8&gt;</td>', 'lol the title goes very well with this photo.  Excellent crispness and colors.  I like the greaan background with the DoF as I find it brings out more colors in the photo.  Well done and good luck in this challenge.  <8>', '2005-08-01 18:14:30.000000', NULL, 1),
(1578831, 211301, 14671, '<td valign="top">A approx. 93 rotation CCW would make this a great entry for the accidental letters challenge but for this challenge it doesn''t do well.  I find it lacks interesting subject and gives a last minute feel to the challenge.  Good luck in this challenge.  &lt;5&gt;</td>', 'A approx. 93 rotation CCW would make this a great entry for the accidental letters challenge but for this challenge it doesn''t do well.  I find it lacks interesting subject and gives a last minute feel to the challenge.  Good luck in this challenge.  <5>', '2005-08-01 18:17:34.000000', NULL, 1),
(1578834, 209262, 14671, '<td valign="top">The lines in the background are very distracting.  I''m also not fond of the green bottle on the smoked colored background.  The lines also show that the photo isn''t straight/level.  Good luck in this chalenge.  &lt;5&gt;</td>', 'The lines in the background are very distracting.  I''m also not fond of the green bottle on the smoked colored background.  The lines also show that the photo isn''t straight/level.  Good luck in this chalenge.  <5>', '2005-08-01 18:19:43.000000', NULL, 1),
(1578836, 211431, 14671, '<td valign="top">Damn theres a huge storm outside now and I can''t figure out the settings I need for this shot.  Excellent clarity and fantastic colors as well as a photo I''d hang on my wall.  Well done and good luck in this challenge.  &lt;9&gt;</td>', 'Damn theres a huge storm outside now and I can''t figure out the settings I need for this shot.  Excellent clarity and fantastic colors as well as a photo I''d hang on my wall.  Well done and good luck in this challenge.  <9>', '2005-08-01 18:21:20.000000', NULL, 1),
(1578841, 210561, 24642, '<td valign="top">Interesting composition and balance here.  I guess this would look good as a big print.  A more creative title would have helped.    -9</td>', 'Interesting composition and balance here.  I guess this would look good as a big print.  A more creative title would have helped.    -9', '2005-08-01 18:23:53.000000', NULL, 1),
(1578843, 210979, 40809, '<td valign="top">Your photo made me heartsick for my hometown...  I like the car being in the photo - it adds an extra dimension most night shots lack.</td>', 'Your photo made me heartsick for my hometown...  I like the car being in the photo - it adds an extra dimension most night shots lack.', '2005-08-01 18:24:18.000000', NULL, 1),
(1578845, 211896, 24642, '<td valign="top">Very well done.</td>', 'Very well done.', '2005-08-01 18:26:04.000000', NULL, 1),
(1578846, 211688, 30791, '<td valign="top">WOOTy<br/>10!</td>', 'WOOTy10!', '2005-08-01 18:26:22.000000', NULL, 1),
(1578847, 210764, 14671, '<td valign="top">You didn''t need to have the time in the title as I find it takes away MORE then it adds.  Excellent clarity and a very interesting shot.  Perhaps a little on the bright side but that could be my monitor.  Well done and good luck in this challenge. &lt;9&gt;</td>', 'You didn''t need to have the time in the title as I find it takes away MORE then it adds.  Excellent clarity and a very interesting shot.  Perhaps a little on the bright side but that could be my monitor.  Well done and good luck in this challenge. <9>', '2005-08-01 18:26:28.000000', NULL, 1),
(1578851, 211386, 3569, '<td valign="top">Who''s is in Pueblo besides me?  Great capture of the depot.</td>', 'Who''s is in Pueblo besides me?  Great capture of the depot.', '2005-08-01 18:28:37.000000', NULL, 1),
(1578852, 210371, 14671, '<td valign="top">I''m not quite sure how this fits the challenge.  I think it would have done better in a time or passing time challenge then this one.  I also find your subject lacks interest and the tilt is crooked.  erhaps a rotation of 1.5 degrees CCW would have straightened this out.  Good luck in this challenge.  &lt;5&gt;</td>', 'I''m not quite sure how this fits the challenge.  I think it would have done better in a time or passing time challenge then this one.  I also find your subject lacks interest and the tilt is crooked.  erhaps a rotation of 1.5 degrees CCW would have straightened this out.  Good luck in this challenge.  <5>', '2005-08-01 18:28:53.000000', NULL, 1),
(1578858, 210738, 24642, '<td valign="top">What strikes me here is the choice of format.  I am generally not fond of the horizonal 4x5 format but this is a welcome exception, I think the format fits perfectlyt.   I like the colours and the double sense of movement by the sea and the wind.  Good luck in the challenge.  -10</td>', 'What strikes me here is the choice of format.  I am generally not fond of the horizonal 4x5 format but this is a welcome exception, I think the format fits perfectlyt.   I like the colours and the double sense of movement by the sea and the wind.  Good luck in the challenge.  -10', '2005-08-01 18:34:16.000000', NULL, 1),
(1578860, 210561, 14671, '<td valign="top">I''m not fond of this picture.  I find it lacks subject or interest.  By this I mean I find it hard to figure out what the subject is.  It does fit the challenge and its OK as far as abstract goes.  God luck in this challenge.  &lt;5&gt;</td>', 'I''m not fond of this picture.  I find it lacks subject or interest.  By this I mean I find it hard to figure out what the subject is.  It does fit the challenge and its OK as far as abstract goes.  God luck in this challenge.  <5>', '2005-08-01 18:35:33.000000', NULL, 1),
(1578862, 211169, 24642, '<td valign="top">Good viewpoint and post processing.  The poetic title works well here.  -9</td>', 'Good viewpoint and post processing.  The poetic title works well here.  -9', '2005-08-01 18:36:48.000000', NULL, 1),
(1578867, 211711, 14671, '<td valign="top">The photo appears to be tilted (the picture on the wall) unless it was shot with a fisheye lense.  I also have a feeling that this photo will get slammed because the "long exposure" is very subtle.  All in all its a semi pleasing photo and the earth tones do a very nice job.  I would like to see a B&amp;W conversion and compare the two.  Well done and good luck in this challenge. &lt;7&gt;</td>', 'The photo appears to be tilted (the picture on the wall) unless it was shot with a fisheye lense.  I also have a feeling that this photo will get slammed because the "long exposure" is very subtle.  All in all its a semi pleasing photo and the earth tones do a very nice job.  I would like to see a B&W conversion and compare the two.  Well done and good luck in this challenge. <7>', '2005-08-01 18:39:48.000000', NULL, 1),
(1578868, 210816, 14671, '<td valign="top">Nicely done but a little to bright.  I like the way the photo appears to hae a golden look about it and the reflection adds a lot to the photo.  Good composition and great clarity.  Well done and good luck in this challenge.  &lt;7&gt;</td>', 'Nicely done but a little to bright.  I like the way the photo appears to hae a golden look about it and the reflection adds a lot to the photo.  Good composition and great clarity.  Well done and good luck in this challenge.  <7>', '2005-08-01 18:41:20.000000', NULL, 1),
(1578875, 211574, 14671, '<td valign="top">Interesting take on this challenge.  I like the dualtone in this image but the subject is lacking interest for me.   I think thats because of the 2 different sized heads.  Well done and good luck in this challenge.  &lt;6&gt;</td>', 'Interesting take on this challenge.  I like the dualtone in this image but the subject is lacking interest for me.   I think thats because of the 2 different sized heads.  Well done and good luck in this challenge.  <6>', '2005-08-01 18:50:29.000000', NULL, 1),
(1578876, 211793, 31620, '<td valign="top">Congrats on this photo.  It is absolutley fantastic!!!!  I really love it.  If I was a member it would have got a 10 for sure!</td>', 'Congrats on this photo.  It is absolutley fantastic!!!!  I really love it.  If I was a member it would have got a 10 for sure!', '2005-08-01 18:50:39.000000', NULL, 1),
(1578878, 211782, 14671, '<td valign="top">A little to bright in my opinion.  Perhaps a -10 brightness and +10 on the contrast would have made for a better photo.  Good luck in this challenge.  &lt;5&gt;</td>', 'A little to bright in my opinion.  Perhaps a -10 brightness and +10 on the contrast would have made for a better photo.  Good luck in this challenge.  <5>', '2005-08-01 18:51:37.000000', NULL, 1),
