(1581158, 210947, 8139, '<td valign="top">Really nice. Like the Floyd tittle too :)</td>', 'Really nice. Like the Floyd tittle too :)', '2005-08-02 18:41:43.000000', NULL, 1),
(1581159, 211788, 19311, '<td valign="top">Awesome shot.  The postition of the person is perfect and really makes this far more than a normal waterfall.</td>', 'Awesome shot.  The postition of the person is perfect and really makes this far more than a normal waterfall.', '2005-08-02 18:42:09.000000', NULL, 1),
(1581163, 211677, 8139, '<td valign="top">Intriguing. Don''t see what it is, but it has a nice aestetic</td>', 'Intriguing. Don''t see what it is, but it has a nice aestetic', '2005-08-02 18:43:30.000000', NULL, 1),
(1581164, 211759, 37103, '<td valign="top">I really like the texture of the rock and the sea.  The bright intense green is too strong for me.  Maybe you could selectively desaturate it a little bit.</td>', 'I really like the texture of the rock and the sea.  The bright intense green is too strong for me.  Maybe you could selectively desaturate it a little bit.', '2005-08-02 18:44:35.000000', NULL, 1),
(1581165, 211785, 8139, '<td valign="top">Very nice dark compo.</td>', 'Very nice dark compo.', '2005-08-02 18:44:40.000000', NULL, 1),
(1581166, 211628, 19311, '<td valign="top">Would do much better flipped right side up.</td>', 'Would do much better flipped right side up.', '2005-08-02 18:45:04.000000', NULL, 1),
(1581172, 211798, 19311, '<td valign="top">Very nice idea and execution, just wish it was a tad lighter. 8</td>', 'Very nice idea and execution, just wish it was a tad lighter. 8', '2005-08-02 18:47:48.000000', NULL, 1),
(1581173, 211714, 16106, '<td valign="top">A bit too yellow IMHO but well framed and I like the mood, I just wish the color balance was more bleuto get the banners better.</td>', 'A bit too yellow IMHO but well framed and I like the mood, I just wish the color balance was more bleuto get the banners better.', '2005-08-02 18:47:54.000000', NULL, 1),
(1581174, 211673, 19311, '<td valign="top">A more creative title would help a little</td>', 'A more creative title would help a little', '2005-08-02 18:48:42.000000', NULL, 1),
(1581175, 210057, 19311, '<td valign="top">this is a great zoom blur. looks like a painting 8</td>', 'this is a great zoom blur. looks like a painting 8', '2005-08-02 18:49:45.000000', NULL, 1),
(1581176, 211816, 16106, '<td valign="top">very pretty shot and I bet it would make a great art print, but too little foreground or upper falls make the water look like it lacks a place to spring from or move into. Great colors and mood.</td>', 'very pretty shot and I bet it would make a great art print, but too little foreground or upper falls make the water look like it lacks a place to spring from or move into. Great colors and mood.', '2005-08-02 18:50:02.000000', NULL, 1),
(1581178, 210136, 19311, '<td valign="top">Stunning image, wish I could be there.  wouldn''t change a thing</td>', 'Stunning image, wish I could be there.  wouldn''t change a thing', '2005-08-02 18:50:37.000000', NULL, 1),
(1581181, 211894, 16106, '<td valign="top">I think it might have been better less centered, the runner seems a bit too static in the frame. Love the foot motion and color contrast between the red and green, i wish there were more of them and less grey.</td>', 'I think it might have been better less centered, the runner seems a bit too static in the frame. Love the foot motion and color contrast between the red and green, i wish there were more of them and less grey.', '2005-08-02 18:51:53.000000', NULL, 1),
(1581182, 211758, 19311, '<td valign="top">i think it would have been even better with the girl on the right third</td>', 'i think it would have been even better with the girl on the right third', '2005-08-02 18:52:10.000000', NULL, 1),
(1581185, 211900, 19311, '<td valign="top">I don''t think the blur really adds to anything in the image.</td>', 'I don''t think the blur really adds to anything in the image.', '2005-08-02 18:53:19.000000', NULL, 1),
(1581187, 211357, 19311, '<td valign="top">Wow, I have no idea how this was done.  Would love to see a setup.</td>', 'Wow, I have no idea how this was done.  Would love to see a setup.', '2005-08-02 18:54:06.000000', NULL, 1),
(1581188, 211895, 16106, '<td valign="top">Well concived and framed shot. It is a shame the backround where most of the action occurs is not as sharp and detail rich as that lovely moss covered rock in the foreground.</td>', 'Well concived and framed shot. It is a shame the backround where most of the action occurs is not as sharp and detail rich as that lovely moss covered rock in the foreground.', '2005-08-02 18:54:09.000000', NULL, 1),
(1581189, 211574, 19311, '<td valign="top">Very good use of color to express mood.   I think the border could be a little smaller.</td>', 'Very good use of color to express mood.   I think the border could be a little smaller.', '2005-08-02 18:55:32.000000', NULL, 1),
(1581190, 211673, 16106, '<td valign="top">great mood  and it works well as an abstract, however i am afraid that it will not score as well as it might since there is no still, sharp point for all the motion to focus on. it reminds me of a Turner water color.</td>', 'great mood  and it works well as an abstract, however i am afraid that it will not score as well as it might since there is no still, sharp point for all the motion to focus on. it reminds me of a Turner water color.', '2005-08-02 18:56:29.000000', NULL, 1),
(1581193, 211820, 16106, '<td valign="top">nice shot, if you could have gotten some color in the sky it would ribbon, as it is, great framing and focus, ought to do well.</td>', 'nice shot, if you could have gotten some color in the sky it would ribbon, as it is, great framing and focus, ought to do well.', '2005-08-02 18:58:06.000000', NULL, 1),
(1581195, 211464, 19311, '<td valign="top">While this a beatiful image, I don''t think it fits the category to well</td>', 'While this a beatiful image, I don''t think it fits the category to well', '2005-08-02 18:58:30.000000', NULL, 1),
(1581196, 209155, 16106, '<td valign="top">nice decision to crop at an angle, and the duotone works well, but I wish the objects on the shelf didn''t block what looks to be a nice expression on your modle''s face.</td>', 'nice decision to crop at an angle, and the duotone works well, but I wish the objects on the shelf didn''t block what looks to be a nice expression on your modle''s face.', '2005-08-02 18:59:58.000000', NULL, 1),
(1581199, 211431, 16106, '<td valign="top">I wish there was a bit more foreground to balance the sky, but the sillouette and sky tone are great, the clouds make the strike even better. nice work.</td>', 'I wish there was a bit more foreground to balance the sky, but the sillouette and sky tone are great, the clouds make the strike even better. nice work.', '2005-08-02 19:02:23.000000', NULL, 1),
(1581201, 211794, 23053, '<td valign="top">My....eyes....are....bleeding!  Quite an impressive effect you''ve got yourself here.  It is certainly fun and colorful, and should do well.  It''s odd, but I guess that since everything is in a circle, the wheel almost looks static.  Perhaps if you can go again, a slightly shorter exposure could give a greater impression of movement.</td>', 'My....eyes....are....bleeding!  Quite an impressive effect you''ve got yourself here.  It is certainly fun and colorful, and should do well.  It''s odd, but I guess that since everything is in a circle, the wheel almost looks static.  Perhaps if you can go again, a slightly shorter exposure could give a greater impression of movement.', '2005-08-02 19:03:32.000000', NULL, 1),
(1581204, 211733, 16106, '<td valign="top">Beautifull, but I wish the bulb was sharper</td>', 'Beautifull, but I wish the bulb was sharper', '2005-08-02 19:05:19.000000', NULL, 1),
(1581205, 211425, 23053, '<td valign="top">This is guh-reat.  The overall blur gives the image a mistical quality and the fact that faces are just visible enough to be made out helps to anchor the image and keep it uber-interesting.  Definately, the more I look, the more I see.  Good job.</td>', 'This is guh-reat.  The overall blur gives the image a mistical quality and the fact that faces are just visible enough to be made out helps to anchor the image and keep it uber-interesting.  Definately, the more I look, the more I see.  Good job.', '2005-08-02 19:05:51.000000', NULL, 1),
(1581209, 211833, 16106, '<td valign="top">very poetic, I love the stages of the falls, though on my monitor the B&amp;W conversion is a bit mossy brown sort of like a shot that was not left in the fixative for long enough.</td>', 'very poetic, I love the stages of the falls, though on my monitor the B&W conversion is a bit mossy brown sort of like a shot that was not left in the fixative for long enough.', '2005-08-02 19:08:23.000000', NULL, 1),
(1581211, 211311, 16106, '<td valign="top">Nice shot but while this may have been taken with a long exposure, it need not have been, so it falls down in the meeting the challenge test.</td>', 'Nice shot but while this may have been taken with a long exposure, it need not have been, so it falls down in the meeting the challenge test.', '2005-08-02 19:09:33.000000', NULL, 1),
(1581213, 210927, 19311, '<td valign="top">Not in focus</td>', 'Not in focus', '2005-08-02 19:10:19.000000', NULL, 1),
(1581214, 210448, 23053, '<td valign="top">I like the blown-out areas and the washed-out colors as they give this shot an ultra-spooky feel that I''m sure you were going for.  Honestly, I find the soap dish distracting, but that''s pretty minor.</td>', 'I like the blown-out areas and the washed-out colors as they give this shot an ultra-spooky feel that I''m sure you were going for.  Honestly, I find the soap dish distracting, but that''s pretty minor.', '2005-08-02 19:11:14.000000', NULL, 1),
(1581221, 211886, 19311, '<td valign="top">Changed your mind from the ''say no evil , hear no  evil, seen no evil'' title? I would like to see more picture and less border.<br/></td>', 'Changed your mind from the ''say no evil , hear no  evil, seen no evil'' title? I would like to see more picture and less border.', '2005-08-02 19:13:48.000000', NULL, 1),
(1581224, 211720, 19311, '<td valign="top">That thing is Huge!  Those people add the perfect perspective.</td>', 'That thing is Huge!  Those people add the perfect perspective.', '2005-08-02 19:14:21.000000', NULL, 1),
(1581225, 210837, 19311, '<td valign="top">Very simple strong image.  Good job</td>', 'Very simple strong image.  Good job', '2005-08-02 19:15:10.000000', NULL, 1),
(1581229, 209156, 23053, '<td valign="top">Geez, dude...eat some fiber!  Anyway, I like the tone of the image - the redness, I mean...not sure if it is a duotone or a tritone or a quadtone or a telephone.  There is a palpable intensity present that I am sure was your goal.  He is the type of guy I hate, as no matter what he does, his hair stays put.  Happy shooting, mon ami!</td>', 'Geez, dude...eat some fiber!  Anyway, I like the tone of the image - the redness, I mean...not sure if it is a duotone or a tritone or a quadtone or a telephone.  There is a palpable intensity present that I am sure was your goal.  He is the type of guy I hate, as no matter what he does, his hair stays put.  Happy shooting, mon ami!', '2005-08-02 19:18:03.000000', NULL, 1),
(1581230, 211855, 19311, '<td valign="top">I''m just itchin to see that far right edge.  Would really draw your eye more.  Still a cool shot 7</td>', 'I''m just itchin to see that far right edge.  Would really draw your eye more.  Still a cool shot 7', '2005-08-02 19:18:08.000000', NULL, 1),
(1581232, 211792, 19311, '<td valign="top">Man that is one cool subject and excellently captured</td>', 'Man that is one cool subject and excellently captured', '2005-08-02 19:19:24.000000', NULL, 1),
(1581236, 210882, 19311, '<td valign="top">Very nice image.  Sharp with lots to draw you into the picture.</td>', 'Very nice image.  Sharp with lots to draw you into the picture.', '2005-08-02 19:21:54.000000', NULL, 1),
(1581241, 211500, 41536, '<td valign="top">I envy the expertise that it take to shot a phot like this!!</td>', 'I envy the expertise that it take to shot a phot like this!!', '2005-08-02 19:24:28.000000', NULL, 1),
(1581242, 211798, 35229, '<td valign="top">These people ruined the picture of a beautyful waterfall.</td>', 'These people ruined the picture of a beautyful waterfall.', '2005-08-02 19:24:51.000000', NULL, 1),
(1581243, 210979, 35229, '<td valign="top">Just great. Love it.</td>', 'Just great. Love it.', '2005-08-02 19:25:23.000000', NULL, 1),
(1581245, 210979, 23053, '<td valign="top">So, how long is the wait in line to take a photo from this place?  2, 3 hours tops?  Thank you, by the way, for including the car in this shot as I think it really helps, since there is no doubt that we have seen shots without the car before.  Also, having the car in adds a deeper story to the image, rather than the more typical ''look at the pretty bridge'' shot...here we, as fellow photographers, understand the desire to get the right shot at the right time, even if it means being out later than normal.  All in all, I think the car makes the image.  Good thinking.</td>', 'So, how long is the wait in line to take a photo from this place?  2, 3 hours tops?  Thank you, by the way, for including the car in this shot as I think it really helps, since there is no doubt that we have seen shots without the car before.  Also, having the car in adds a deeper story to the image, rather than the more typical ''look at the pretty bridge'' shot...here we, as fellow photographers, understand the desire to get the right shot at the right time, even if it means being out later than normal.  All in all, I think the car makes the image.  Good thinking.', '2005-08-02 19:26:09.000000', NULL, 1),
(1581246, 210726, 35229, '<td valign="top">Looks professional.</td>', 'Looks professional.', '2005-08-02 19:26:13.000000', NULL, 1),
(1581247, 210927, 35229, '<td valign="top">Hmm peeping Tom.</td>', 'Hmm peeping Tom.', '2005-08-02 19:26:37.000000', NULL, 1),
(1581249, 211759, 35229, '<td valign="top">Wow! 10! It is just great!</td>', 'Wow! 10! It is just great!', '2005-08-02 19:28:06.000000', NULL, 1),
(1581250, 211886, 23053, '<td valign="top">So, which is which?  Sorry, I couldn''t resist.  I like the costume changes...really helps to make this more interesting than the typical shot like this.  I think the border is unnecessary and makes this look a bit like a fridge magnet.</td>', 'So, which is which?  Sorry, I couldn''t resist.  I like the costume changes...really helps to make this more interesting than the typical shot like this.  I think the border is unnecessary and makes this look a bit like a fridge magnet.', '2005-08-02 19:30:31.000000', NULL, 1),
(1581251, 210882, 6104, '<td valign="top">I like this but I think it would benefit if the frame were straigtened to match the edge of the building on the left. 8</td>', 'I like this but I think it would benefit if the frame were straigtened to match the edge of the building on the left. 8', '2005-08-02 19:31:23.000000', NULL, 1),
(1581253, 210453, 23053, '<td valign="top">I think if you had had a tighter crop on the swings and the edge of the disk this shot could have been more dramatic - say the rightmost third of the image, stopping above the tent top.  I like how a number of the swingers are fairly clear as it adds interest.</td>', 'I think if you had had a tighter crop on the swings and the edge of the disk this shot could have been more dramatic - say the rightmost third of the image, stopping above the tent top.  I like how a number of the swingers are fairly clear as it adds interest.', '2005-08-02 19:33:16.000000', NULL, 1),
(1581261, 210057, 24642, '<td valign="top">I really like the composition and the tones.</td>', 'I really like the composition and the tones.', '2005-08-02 20:03:04.000000', NULL, 1),
(1581264, 211214, 25906, '<td valign="top">Nice shot!</td>', 'Nice shot!', '2005-08-02 20:05:45.000000', NULL, 1),
(1581283, 211787, 164, '<td valign="top">too bright.</td>', 'too bright.', '2005-08-02 20:27:00.000000', NULL, 1),
(1581289, 211464, 25890, '<td valign="top">Colors are gorgeous, and the exposure seems accurate. Composition is a bit awkward, I''m afraid. I don''t quite mind the horizon being right in the middle but the pier cutting across the frame, and lack of foreground interest or some other kind of front-to-back lead cause the image to appear static and only 2-dimensional.</td>', 'Colors are gorgeous, and the exposure seems accurate. Composition is a bit awkward, I''m afraid. I don''t quite mind the horizon being right in the middle but the pier cutting across the frame, and lack of foreground interest or some other kind of front-to-back lead cause the image to appear static and only 2-dimensional.', '2005-08-02 20:28:47.000000', NULL, 1),
(1581300, 211788, 41536, '<td valign="top">I really like the composition.  I don''t know why, but the climber works well!  Great job.</td>', 'I really like the composition.  I don''t know why, but the climber works well!  Great job.', '2005-08-02 20:36:24.000000', NULL, 1),
(1581330, 209941, 24642, '<td valign="top">Looks like a Aznym signature shot.  Good flow, speed and the strong whites.<br/>Good work.</td>', 'Looks like a Aznym signature shot.  Good flow, speed and the strong whites.Good work.', '2005-08-02 21:04:55.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1581331, 211806, 24642, '<td valign="top">I like the colours and the speed.<br/>I am surprised that there weren''t more shots that use this technique.  Can''t see the reason for validation.</td>', 'I like the colours and the speed.I am surprised that there weren''t more shots that use this technique.  Can''t see the reason for validation.', '2005-08-02 21:07:11.000000', NULL, 1),
(1581336, 211821, 24642, '<td valign="top">Good flow and strong textures.  I like the closeness to the stream.  Perhaps a tad oversaturated.  Anyway good work.</td>', 'Good flow and strong textures.  I like the closeness to the stream.  Perhaps a tad oversaturated.  Anyway good work.', '2005-08-02 21:09:20.000000', NULL, 1),
