INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1584302, 210448, 21714, '<td valign="top">Love the spookiness in this one. The highlights and brownish tint all around, suits it well.</td>', 'Love the spookiness in this one. The highlights and brownish tint all around, suits it well.', '2005-08-03 15:41:36.000000', NULL, 1),
(1584304, 210816, 41522, '<td valign="top">Nicely composed and the colour of the lights is great.  Nice photo.</td>', 'Nicely composed and the colour of the lights is great.  Nice photo.', '2005-08-03 15:42:13.000000', NULL, 1),
(1584306, 210983, 21714, '<td valign="top">Tilted angle makes the image extremely dynamic and pulls you right into the scene. Well done.</td>', 'Tilted angle makes the image extremely dynamic and pulls you right into the scene. Well done.', '2005-08-03 15:42:34.000000', NULL, 1),
(1584316, 211709, 21714, '<td valign="top">Very high energy shot. I can feel the blood pumping.</td>', 'Very high energy shot. I can feel the blood pumping.', '2005-08-03 15:44:30.000000', NULL, 1),
(1584317, 211611, 41522, '<td valign="top">Yep, That''s how I remember London... non-stop traffic going all over the city.  I''m glad that the lights in the foreground are only green so that it adds to the "Go" feeling.</td>', 'Yep, That''s how I remember London... non-stop traffic going all over the city.  I''m glad that the lights in the foreground are only green so that it adds to the "Go" feeling.', '2005-08-03 15:44:33.000000', NULL, 1),
(1584322, 210837, 41522, '<td valign="top">I really like the composition of this.  I think the photo could have been a little stronger if the darkest, most solid part of the movement was on the left instead of higher up the stairs on the right.  This almost has the feel that the person is walking backwards up the stairs.</td>', 'I really like the composition of this.  I think the photo could have been a little stronger if the darkest, most solid part of the movement was on the left instead of higher up the stairs on the right.  This almost has the feel that the person is walking backwards up the stairs.', '2005-08-03 15:47:28.000000', NULL, 1),
(1584323, 210138, 41522, '<td valign="top">I like the motion of this.  I don''t know if it is posible, but it would have been really cool if you could have had a few keys appears as being down.  Good photo though.</td>', 'I like the motion of this.  I don''t know if it is posible, but it would have been really cool if you could have had a few keys appears as being down.  Good photo though.', '2005-08-03 15:48:58.000000', NULL, 1),
(1584324, 211500, 41522, '<td valign="top">Beautiful shot.  Looks like a good celebration.</td>', 'Beautiful shot.  Looks like a good celebration.', '2005-08-03 15:50:18.000000', NULL, 1),
(1584329, 210057, 21714, '<td valign="top">This says TIME to me. Maybe because of how they show time-travel in the movies. It may also be because I see a person''s lifepath in this one. I see a person who has paused  to give us a brief glimpse of his character. It''s like he''s paused at teh doorsteps of a very bright future. This one highly intrigues me.</td>', 'This says TIME to me. Maybe because of how they show time-travel in the movies. It may also be because I see a person''s lifepath in this one. I see a person who has paused  to give us a brief glimpse of his character. It''s like he''s paused at teh doorsteps of a very bright future. This one highly intrigues me.', '2005-08-03 15:52:31.000000', NULL, 1),
(1584389, 211016, 38921, '<td valign="top">Really tough to pull this shot off with just a single exposure.  THe noise in the upper left and the glare across the middle are distracting.  Alos, I would have liked to see more foreground elements to provide additional interest.<br/> <br/>Theme 3/3<br/>Composition 0/2<br/>Technical 1/2 <br/>Image Impact 0/3<br/> <br/></td>', 'Really tough to pull this shot off with just a single exposure.  THe noise in the upper left and the glare across the middle are distracting.  Alos, I would have liked to see more foreground elements to provide additional interest. Theme 3/3Composition 0/2Technical 1/2 Image Impact 0/3 ', '2005-08-03 16:16:19.000000', NULL, 1),
(1584401, 209997, 38921, '<td valign="top">Theme 3/3<br/>Composition 0/2<br/>Technical 0/2<br/>Image Impact 0/3<br/> <br/>The image is underexposed and the composition does nothing to provide interest of the subjects.  <br/> <br/></td>', 'Theme 3/3Composition 0/2Technical 0/2Image Impact 0/3 The image is underexposed and the composition does nothing to provide interest of the subjects.   ', '2005-08-03 16:19:30.000000', NULL, 1),
(1584429, 211758, 38921, '<td valign="top">Theme 3/3<br/>Composition 2/2<br/>Technical 2/2<br/>Image Impact 2/3<br/> <br/>Not sure if this would have been better with the "ghost" place next to the cross instead of over it.  Not taking any deductions for it, just a thought.</td>', 'Theme 3/3Composition 2/2Technical 2/2Image Impact 2/3 Not sure if this would have been better with the "ghost" place next to the cross instead of over it.  Not taking any deductions for it, just a thought.', '2005-08-03 16:25:22.000000', NULL, 1),
(1584434, 211855, 38921, '<td valign="top">Theme 3/3<br/>Composition 2/2<br/>Technical 1/2<br/>Image Impact 3/3<br/> <br/>Only deduction is for the white blotch just above the first light.  Since this was an advanced editing challenge I would have preferred to see it cloned out.</td>', 'Theme 3/3Composition 2/2Technical 1/2Image Impact 3/3 Only deduction is for the white blotch just above the first light.  Since this was an advanced editing challenge I would have preferred to see it cloned out.', '2005-08-03 16:28:14.000000', NULL, 1),
