(1588883, 211806, 38078, '<td valign="top">wonderful effect!  My head is spinning.  works like a field of poppies.</td>', 'wonderful effect!  My head is spinning.  works like a field of poppies.', '2005-08-05 14:12:20.000000', NULL, 1),
(1588886, 210298, 38078, '<td valign="top">great shot!  well orchestrated.</td>', 'great shot!  well orchestrated.', '2005-08-05 14:15:19.000000', NULL, 1),
(1588890, 211632, 32117, '<td valign="top">good long exposure!<br/>good use of starburst filter!<br/></td>', 'good long exposure!good use of starburst filter!', '2005-08-05 14:21:21.000000', NULL, 1),
(1588893, 209895, 32117, '<td valign="top">great work!<br/></td>', 'great work!', '2005-08-05 14:23:27.000000', NULL, 1),
(1588900, 210738, 32117, '<td valign="top">great pic!</td>', 'great pic!', '2005-08-05 14:28:16.000000', NULL, 1),
(1588922, 210927, 3102, '<td valign="top">Dang... I *really* wish this one was in focus!  :)</td>', 'Dang... I *really* wish this one was in focus!  :)', '2005-08-05 14:41:34.000000', NULL, 1),
(1589014, 211838, 9089, '<td valign="top">Has a good graphics art feel to the shot.  Wish there wasn''t as much grain in the photo, but overall, the long exposure makes the shot interesting.  7</td>', 'Has a good graphics art feel to the shot.  Wish there wasn''t as much grain in the photo, but overall, the long exposure makes the shot interesting.  7', '2005-08-05 15:52:31.000000', NULL, 1),
(1589016, 211673, 9089, '<td valign="top">Interesting/uninteresting photo.  Here''s what I mean, the lights blurring into the photo do make an interesting dynamic, however, that is all the dynamic in the shot, and there is nothing that makes me want to stay and ponder it, once I''ve seen the lines of the lights, that''s all.  The ''tower'' in the middle doesn''t have enough detail/recognizable elements to hold the attention for long.  6</td>', 'Interesting/uninteresting photo.  Here''s what I mean, the lights blurring into the photo do make an interesting dynamic, however, that is all the dynamic in the shot, and there is nothing that makes me want to stay and ponder it, once I''ve seen the lines of the lights, that''s all.  The ''tower'' in the middle doesn''t have enough detail/recognizable elements to hold the attention for long.  6', '2005-08-05 15:54:13.000000', NULL, 1),
(1589018, 211733, 9089, '<td valign="top">If that lightbulb would be sharp, this would be a ribbon winner.  It is a fantastic effect.  Lighting is great.  Just the sharpness of the bulb that holds the picture back.  6</td>', 'If that lightbulb would be sharp, this would be a ribbon winner.  It is a fantastic effect.  Lighting is great.  Just the sharpness of the bulb that holds the picture back.  6', '2005-08-05 15:55:09.000000', NULL, 1),
(1589021, 210298, 9089, '<td valign="top">There''s been several of these lately, and that may be weighing in on my voting, sorry.  I guess the biggest problem I have with this photo is the line of fire going across the forehead which is very distracting to the person in the midst of the fire.  6</td>', 'There''s been several of these lately, and that may be weighing in on my voting, sorry.  I guess the biggest problem I have with this photo is the line of fire going across the forehead which is very distracting to the person in the midst of the fire.  6', '2005-08-05 15:58:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1589025, 211479, 9089, '<td valign="top">Pretty image.  Compositionally, the little pipe sticking up, mirroring the lighthouse in the background help to form an implied trangle tying it with the rocks.  The colors just seem flat and lifeless though.  6</td>', 'Pretty image.  Compositionally, the little pipe sticking up, mirroring the lighthouse in the background help to form an implied trangle tying it with the rocks.  The colors just seem flat and lifeless though.  6', '2005-08-05 16:00:55.000000', NULL, 1),
(1589027, 211628, 24550, '<td valign="top">not sure why this is upside down</td>', 'not sure why this is upside down', '2005-08-05 16:01:16.000000', NULL, 1),
(1589028, 209188, 9089, '<td valign="top">I''m thinking that there needs to be something more to see in this picture.  It seems off-balance, and needs something to help it be more interesting.  6</td>', 'I''m thinking that there needs to be something more to see in this picture.  It seems off-balance, and needs something to help it be more interesting.  6', '2005-08-05 16:01:47.000000', NULL, 1),
(1589033, 211782, 9089, '<td valign="top">I think that this is a good photo.  The concept, composition are great.  I think what holds it back from being a fantastic photo is the over brightness of the image.  A spinning top to me holds images of childhood, and that to me is very vibrant colors, the whiteness of the picture almost blows out the good purple color of the top.  6</td>', 'I think that this is a good photo.  The concept, composition are great.  I think what holds it back from being a fantastic photo is the over brightness of the image.  A spinning top to me holds images of childhood, and that to me is very vibrant colors, the whiteness of the picture almost blows out the good purple color of the top.  6', '2005-08-05 16:04:14.000000', NULL, 1),
(1589041, 211559, 9089, '<td valign="top">Good capture, fisheye lens?  Does look futuristic.  However, what looks like a tire in the foreground doesn''t seem to match with the rest of the photo.  6</td>', 'Good capture, fisheye lens?  Does look futuristic.  However, what looks like a tire in the foreground doesn''t seem to match with the rest of the photo.  6', '2005-08-05 16:09:37.000000', NULL, 1),
(1589044, 211292, 9089, '<td valign="top">Interesting shot.  The felt ont he bottom of the top piece needs to be fixed.  Also, the composition of the pieces seems more jumbled and not really appealing.  However, I still like the shot.  6</td>', 'Interesting shot.  The felt ont he bottom of the top piece needs to be fixed.  Also, the composition of the pieces seems more jumbled and not really appealing.  However, I still like the shot.  6', '2005-08-05 16:11:14.000000', NULL, 1),
(1589046, 210821, 9089, '<td valign="top">Although I like these kinds of shots, and this one is ok, there are a few things that make it unappealing (although they may simply be a result of the small image size), and that is the color and shape of the rocks the water is flowing over.  They look politely saying like brown mud (unpolitely you can guess, but better have some TP with you).  Maybe a tighter crop on just one of the falls, concentrating the focus on it, instead of the 2 competing falls making the eye pingpong back and forth would help as well.  6</td>', 'Although I like these kinds of shots, and this one is ok, there are a few things that make it unappealing (although they may simply be a result of the small image size), and that is the color and shape of the rocks the water is flowing over.  They look politely saying like brown mud (unpolitely you can guess, but better have some TP with you).  Maybe a tighter crop on just one of the falls, concentrating the focus on it, instead of the 2 competing falls making the eye pingpong back and forth would help as well.  6', '2005-08-05 16:13:40.000000', NULL, 1),
(1589047, 210837, 9089, '<td valign="top">Great simple composition as well as movement implied through the motion blur.  Unfortunately with the man''s silhouette being stronger at the first, it makes him seem as if he is going backwards, if you could do this with the stronger image to the front so as to confirm the movement forward, this would jump up to the top of the pack.  6</td>', 'Great simple composition as well as movement implied through the motion blur.  Unfortunately with the man''s silhouette being stronger at the first, it makes him seem as if he is going backwards, if you could do this with the stronger image to the front so as to confirm the movement forward, this would jump up to the top of the pack.  6', '2005-08-05 16:15:09.000000', NULL, 1),
(1589050, 211821, 9089, '<td valign="top">Beautiful flowing water shot.  The orange colors in the bottom left have a luminescence that would be even more gorgeous if it was spread throughout the image.  As it is, it seems to be an anachronism with the jumble of stuff to the top right of the image.  6</td>', 'Beautiful flowing water shot.  The orange colors in the bottom left have a luminescence that would be even more gorgeous if it was spread throughout the image.  As it is, it seems to be an anachronism with the jumble of stuff to the top right of the image.  6', '2005-08-05 16:16:55.000000', NULL, 1),
(1589073, 211500, 9089, '<td valign="top">If it weren''t for that cloud cutting through the firework, this would be great.  I know you took a long exposure on this, but it ended up giving the wierd red lights in the smoke, adn the smaller firework behind the bright one.  Maybe a levels adjustment to make the brown sky black would help.  5</td>', 'If it weren''t for that cloud cutting through the firework, this would be great.  I know you took a long exposure on this, but it ended up giving the wierd red lights in the smoke, adn the smaller firework behind the bright one.  Maybe a levels adjustment to make the brown sky black would help.  5', '2005-08-05 16:34:23.000000', NULL, 1),
(1589286, 211849, 19311, '<td valign="top">Very cool shot, i wish it was a tad sharper but you can only ask for so much on a bumpy ATV.  The trail really brings you into the picture.</td>', 'Very cool shot, i wish it was a tad sharper but you can only ask for so much on a bumpy ATV.  The trail really brings you into the picture.', '2005-08-05 18:56:00.000000', NULL, 1),
(1589288, 209838, 19311, '<td valign="top">Cool shot but I wish the background was solid.</td>', 'Cool shot but I wish the background was solid.', '2005-08-05 18:56:29.000000', NULL, 1),
(1589294, 211721, 19311, '<td valign="top">Shows up a little dark on my screen</td>', 'Shows up a little dark on my screen', '2005-08-05 18:58:06.000000', NULL, 1),
(1589298, 211677, 19311, '<td valign="top">Cool shot, very surreal.  I wish the owl was a little higher in the frame.</td>', 'Cool shot, very surreal.  I wish the owl was a little higher in the frame.', '2005-08-05 18:59:05.000000', NULL, 1),
(1589303, 210979, 19311, '<td valign="top">This  picture is spectacular.  With a little more car, I feel like this should be straight into an advertisement.  Easy 10</td>', 'This  picture is spectacular.  With a little more car, I feel like this should be straight into an advertisement.  Easy 10', '2005-08-05 19:01:06.000000', NULL, 1),
(1589306, 211745, 19311, '<td valign="top">Cool pic to look at.  There is a lot of unused space up top.  I would rather see more of the ground with the top stopping at the roof of the train.</td>', 'Cool pic to look at.  There is a lot of unused space up top.  I would rather see more of the ground with the top stopping at the roof of the train.', '2005-08-05 19:02:38.000000', NULL, 1),
(1589309, 210448, 19311, '<td valign="top">Thats a pretty creepy shot.   Why untitled?  I think a title will only help in 99.9% of pictures</td>', 'Thats a pretty creepy shot.   Why untitled?  I think a title will only help in 99.9% of pictures', '2005-08-05 19:03:56.000000', NULL, 1),
(1589313, 211493, 19311, '<td valign="top">Can''t tell this is at sunrise so I would drop that part of the title.  Nice simple shot</td>', 'Can''t tell this is at sunrise so I would drop that part of the title.  Nice simple shot', '2005-08-05 19:06:40.000000', NULL, 1),
(1589317, 211548, 19311, '<td valign="top">Very cool shot but I''m itchin to see the circle frame his feet as well</td>', 'Very cool shot but I''m itchin to see the circle frame his feet as well', '2005-08-05 19:09:08.000000', NULL, 1),
(1589336, 211794, 23478, '<td valign="top">Excellent photo, the angle gives the illusion of it being tilted.</td>', 'Excellent photo, the angle gives the illusion of it being tilted.', '2005-08-05 19:30:05.000000', NULL, 1),
(1589339, 211733, 23478, '<td valign="top">Interesting photo...  I like the subtle blue hue.</td>', 'Interesting photo...  I like the subtle blue hue.', '2005-08-05 19:32:19.000000', NULL, 1),
(1589341, 211688, 23478, '<td valign="top">Great shot, I like the subtle lighting.</td>', 'Great shot, I like the subtle lighting.', '2005-08-05 19:33:22.000000', NULL, 1),
(1589344, 211895, 23478, '<td valign="top">Good shot, maybe it would benefit from a tighter crop.</td>', 'Good shot, maybe it would benefit from a tighter crop.', '2005-08-05 19:33:48.000000', NULL, 1),
(1589345, 210816, 23478, '<td valign="top">Great shot, this could be a postcard:)</td>', 'Great shot, this could be a postcard:)', '2005-08-05 19:34:34.000000', NULL, 1),
(1589370, 210298, 35274, '<td valign="top">Wow, very cool, to say the least. Gotta know how you did this!</td>', 'Wow, very cool, to say the least. Gotta know how you did this!', '2005-08-05 19:53:12.000000', NULL, 1),
(1589374, 211313, 35274, '<td valign="top">Very interesting! Not sure how I feel about the musical notes...they definately add a whimsical feel to an otherwise (well, in my opinion) gloomy, ghost photo. Gotta know how you did them tho:-)</td>', 'Very interesting! Not sure how I feel about the musical notes...they definately add a whimsical feel to an otherwise (well, in my opinion) gloomy, ghost photo. Gotta know how you did them tho:-)', '2005-08-05 19:56:22.000000', NULL, 1),
(1589380, 209941, 35274, '<td valign="top">Wow, you really made the motion blur work here! Love the concept, and how you used the rule of thirds. A very beautiful photo.</td>', 'Wow, you really made the motion blur work here! Love the concept, and how you used the rule of thirds. A very beautiful photo.', '2005-08-05 19:57:55.000000', NULL, 1),
(1589384, 211792, 35274, '<td valign="top">amazing colors and smoothness. a very beautiful, radiant pic. Good luck!</td>', 'amazing colors and smoothness. a very beautiful, radiant pic. Good luck!', '2005-08-05 19:59:49.000000', NULL, 1),
(1589389, 211864, 35274, '<td valign="top">Very cool. Tho the eyes might be a little too faded IMO. I can see them, but just barely when I tilted my screen towards me. Some people may not be able to do that and might just assume you took a pic of some candles (which isn''t necesarily bad, considering the candles are quite beautiful) but it misses the point of the image. Either way, nicely done, and good luck.</td>', 'Very cool. Tho the eyes might be a little too faded IMO. I can see them, but just barely when I tilted my screen towards me. Some people may not be able to do that and might just assume you took a pic of some candles (which isn''t necesarily bad, considering the candles are quite beautiful) but it misses the point of the image. Either way, nicely done, and good luck.', '2005-08-05 20:04:37.000000', NULL, 1),
(1589424, 211785, 14671, '<td valign="top">Damn this is what I was trying to shoot 15 min ago and couldn''t figure out the settings.  Nicely done.  Good luck in this challenge.</td>', 'Damn this is what I was trying to shoot 15 min ago and couldn''t figure out the settings.  Nicely done.  Good luck in this challenge.', '2005-08-05 20:23:00.000000', NULL, 1),
(1589433, 211896, 3102, '<td valign="top">Certainly looks Heida-esque to me!  Another awesome shot!</td>', 'Certainly looks Heida-esque to me!  Another awesome shot!', '2005-08-05 20:29:12.000000', NULL, 1),
(1589479, 211628, 37234, '<td valign="top">Interesting. An upside down photo. I''m assuming this was intentional. Very interesting.</td>', 'Interesting. An upside down photo. I''m assuming this was intentional. Very interesting.', '2005-08-05 21:05:50.000000', NULL, 1),
(1589482, 211790, 37234, '<td valign="top">I''d almost swear this is in the aviary at the San Diego Zoo. Great shot.</td>', 'I''d almost swear this is in the aviary at the San Diego Zoo. Great shot.', '2005-08-05 21:07:46.000000', NULL, 1),
(1589483, 210882, 37234, '<td valign="top">This would be such a great shot if it was rotated just a tad CCW to even the "horizon"</td>', 'This would be such a great shot if it was rotated just a tad CCW to even the "horizon"', '2005-08-05 21:08:18.000000', NULL, 1),
(1589496, 211896, 37234, '<td valign="top">OK, I can''t decide. I''ve bumped and bumped, and yours is up to 10 - tied with one other. Very very good entry (and I think I know who this is).</td>', 'OK, I can''t decide. I''ve bumped and bumped, and yours is up to 10 - tied with one other. Very very good entry (and I think I know who this is).', '2005-08-05 21:17:35.000000', NULL, 1),
(1589500, 210425, 37234, '<td valign="top">I''m very interested to see how this one does. I gave you a 10. This definately doesn''t fall within the spectrum of what I think will get voted to the top because it''s too sad, emotional, and the photo has a old and scratchy feel to it. But that''s precisely why I like it. Great emotion capture.</td>', 'I''m very interested to see how this one does. I gave you a 10. This definately doesn''t fall within the spectrum of what I think will get voted to the top because it''s too sad, emotional, and the photo has a old and scratchy feel to it. But that''s precisely why I like it. Great emotion capture.', '2005-08-05 21:21:10.000000', NULL, 1),
(1589590, 211896, 4226, '<td valign="top">heida ?</td>', 'heida ?', '2005-08-05 21:56:42.000000', NULL, 1),
(1589616, 210448, 35602, '<td valign="top">Interesting shot.  I think that it is allowed to burn in detail.  The tub was too overexposed.  Just touching it up with a slightly darker color would have really made the photo hard to beat.</td>', 'Interesting shot.  I think that it is allowed to burn in detail.  The tub was too overexposed.  Just touching it up with a slightly darker color would have really made the photo hard to beat.', '2005-08-05 22:16:19.000000', NULL, 1),
(1589618, 211440, 35602, '<td valign="top">Although it depicts motion, I think at least some part should have been focused.</td>', 'Although it depicts motion, I think at least some part should have been focused.', '2005-08-05 22:17:19.000000', NULL, 1),
(1589619, 211877, 35602, '<td valign="top">Too much blur.</td>', 'Too much blur.', '2005-08-05 22:17:37.000000', NULL, 1),
(1589626, 210724, 35602, '<td valign="top">Without knowing it was long exposure, I would not have seen that aspect of it.</td>', 'Without knowing it was long exposure, I would not have seen that aspect of it.', '2005-08-05 22:19:19.000000', NULL, 1),
(1589627, 211896, 35602, '<td valign="top">Liked the affect of the figure.  would have liked to see more of the figure.</td>', 'Liked the affect of the figure.  would have liked to see more of the figure.', '2005-08-05 22:19:51.000000', NULL, 1),
(1589628, 211558, 35602, '<td valign="top">It would have been a stronger image if some part of it was in focus.</td>', 'It would have been a stronger image if some part of it was in focus.', '2005-08-05 22:20:48.000000', NULL, 1),
(1589629, 209262, 35602, '<td valign="top">The image has strips across it.  I am not sure if that is from the motion, but it is over the entire image.  It wrecks the smoothness of the background.</td>', 'The image has strips across it.  I am not sure if that is from the motion, but it is over the entire image.  It wrecks the smoothness of the background.', '2005-08-05 22:21:58.000000', NULL, 1),
(1589637, 210513, 35602, '<td valign="top">Pretty image.   Didn''t get the feeling of long exposure, though,.</td>', 'Pretty image.   Didn''t get the feeling of long exposure, though,.', '2005-08-05 22:24:52.000000', NULL, 1),
(1589639, 210943, 35602, '<td valign="top">I know you were trying to depict motion, but the impact was not really made in the image as it stands.  Not sure what you could do to make the swing look like it was moving without appearing blurry.</td>', 'I know you were trying to depict motion, but the impact was not really made in the image as it stands.  Not sure what you could do to make the swing look like it was moving without appearing blurry.', '2005-08-05 22:26:28.000000', NULL, 1),
(1589645, 211721, 35602, '<td valign="top">Don''t know how long you kept your shutter open, but it needed more time to better capture the stars and their movement.  I know one person that set their shutter on bulb, left it open when they went to bed, and came out five hours later.  That was a really awesome image.</td>', 'Don''t know how long you kept your shutter open, but it needed more time to better capture the stars and their movement.  I know one person that set their shutter on bulb, left it open when they went to bed, and came out five hours later.  That was a really awesome image.', '2005-08-05 22:28:58.000000', NULL, 1),
(1589647, 211492, 35602, '<td valign="top">Very nice and moody.  Great job.</td>', 'Very nice and moody.  Great job.', '2005-08-05 22:29:44.000000', NULL, 1),
(1589648, 211792, 35602, '<td valign="top">Loved the water on this one.  It could have been just as strong without the city skyline.</td>', 'Loved the water on this one.  It could have been just as strong without the city skyline.', '2005-08-05 22:31:29.000000', NULL, 1),
(1589651, 211871, 35602, '<td valign="top">Very cool shot.</td>', 'Very cool shot.', '2005-08-05 22:32:06.000000', NULL, 1),
(1589652, 211851, 35602, '<td valign="top">Needed better focus on the background.</td>', 'Needed better focus on the background.', '2005-08-05 22:33:01.000000', NULL, 1),
(1589654, 211861, 35602, '<td valign="top">Didn''t care for the subject.</td>', 'Didn''t care for the subject.', '2005-08-05 22:33:50.000000', NULL, 1),
(1589656, 210057, 35602, '<td valign="top">Nice attempt.  Thougjt ot was way overexposed.</td>', 'Nice attempt.  Thougjt ot was way overexposed.', '2005-08-05 22:34:26.000000', NULL, 1),
(1589660, 209906, 35602, '<td valign="top">Not sure what you did.  It looks as if you moved the camera up to get the streaks of light.  It does show motion, but there seems to be to much exposure on the pins.  Did you try to get perhaps a bowling ball going down the alley?  The colors are really nice on the shot, but it seems that the technique didn''t work.</td>', 'Not sure what you did.  It looks as if you moved the camera up to get the streaks of light.  It does show motion, but there seems to be to much exposure on the pins.  Did you try to get perhaps a bowling ball going down the alley?  The colors are really nice on the shot, but it seems that the technique didn''t work.', '2005-08-05 22:37:12.000000', NULL, 1),
(1589661, 211758, 35602, '<td valign="top">Creepy.</td>', 'Creepy.', '2005-08-05 22:38:12.000000', NULL, 1),
(1589669, 210973, 35602, '<td valign="top">Did you get a lot of flak about your shadow shot?  I know I did.  Apparently, nobody appreciates shadows in long exposures.  Yours is probably better than mine.  At least you have part of it in focus, which was the main bad comment about mine.</td>', 'Did you get a lot of flak about your shadow shot?  I know I did.  Apparently, nobody appreciates shadows in long exposures.  Yours is probably better than mine.  At least you have part of it in focus, which was the main bad comment about mine.', '2005-08-05 22:41:16.000000', NULL, 1),
(1589671, 209941, 35602, '<td valign="top">Way overexposed.</td>', 'Way overexposed.', '2005-08-05 22:42:00.000000', NULL, 1),
(1589677, 211214, 35602, '<td valign="top">Looks like you did a lot of layers on this one.  Interesting affect.</td>', 'Looks like you did a lot of layers on this one.  Interesting affect.', '2005-08-05 22:43:56.000000', NULL, 1),
(1589709, 210561, 36102, '<td valign="top">I cna''t tell what this is.   It could be a flower with camera movement or it could be something falling?</td>', 'I cna''t tell what this is.   It could be a flower with camera movement or it could be something falling?', '2005-08-05 23:00:49.000000', NULL, 1),
(1589713, 210738, 31606, '<td valign="top">My favorite in this challenge.  I just don''t know what it is but I love it.  The simplicity of the shot mixed with the force of an ocean wav and the bright red just does something for me.  In short this shot "ROCKS"</td>', 'My favorite in this challenge.  I just don''t know what it is but I love it.  The simplicity of the shot mixed with the force of an ocean wav and the bright red just does something for me.  In short this shot "ROCKS"', '2005-08-05 23:04:05.000000', NULL, 1),
(1589723, 211896, 31606, '<td valign="top">Ver nice.  The only thing that bothers me is I think it is just a little too dark.  I know you were probably shooting for this but I think one notch lighter and it is perfect.  Still a 9</td>', 'Ver nice.  The only thing that bothers me is I think it is just a little too dark.  I know you were probably shooting for this but I think one notch lighter and it is perfect.  Still a 9', '2005-08-05 23:08:37.000000', NULL, 1),
(1589726, 210138, 12730, '<td valign="top">Beautifully done!</td>', 'Beautifully done!', '2005-08-05 23:10:31.000000', NULL, 1),
(1589827, 211759, 37234, '<td valign="top">bumping to 9</td>', 'bumping to 9', '2005-08-06 00:03:18.000000', NULL, 1),
(1589828, 211548, 37234, '<td valign="top">I predict a ribbon!!</td>', 'I predict a ribbon!!', '2005-08-06 00:03:41.000000', NULL, 1),
(1589867, 211357, 41888, '<td valign="top">Strong abstract form and lines.</td>', 'Strong abstract form and lines.', '2005-08-06 00:29:14.000000', NULL, 1),
(1589878, 210425, 21816, '<td valign="top">One of my favourites! Really moody! I recognise the face too! :)   Well done!</td>', 'One of my favourites! Really moody! I recognise the face too! :)   Well done!', '2005-08-06 00:32:15.000000', NULL, 1),
(1589924, 210943, 17279, '<td valign="top">I think I understand what you were going for.  I think the exposure was not long enough (not enough sense of motion) or perhaps if shot from a different angle.</td>', 'I think I understand what you were going for.  I think the exposure was not long enough (not enough sense of motion) or perhaps if shot from a different angle.', '2005-08-06 00:53:42.000000', NULL, 1),
(1589927, 211628, 17279, '<td valign="top">It took me a bit to realize you flipped the image.  Really, to me it is somewhat disorienting... this idea might have worked better with a daytime scene.</td>', 'It took me a bit to realize you flipped the image.  Really, to me it is somewhat disorienting... this idea might have worked better with a daytime scene.', '2005-08-06 00:55:30.000000', NULL, 1),
(1589939, 211425, 17279, '<td valign="top">On revisiting this, I think I have to bump it up. I like the colors a lot, but who are these lost souls? is there a theme or connection there?  I can''t make it out... I think if you were able to make that connection visually, this would be a very powerful piece.</td>', 'On revisiting this, I think I have to bump it up. I like the colors a lot, but who are these lost souls? is there a theme or connection there?  I can''t make it out... I think if you were able to make that connection visually, this would be a very powerful piece.', '2005-08-06 00:58:44.000000', NULL, 1),
(1589943, 211692, 20530, '<td valign="top">I like this. I gave it a 7. Can''t really articulate what it is that I like about it, but I''m definitely drawn to the street on the right. It seems to quiet and deserted, though it looks like a place you wouldn''t want to be late at night. It''s also very crisp for a long exposure and the darkness doesn''t bother me. It feels balanced to me.</td>', 'I like this. I gave it a 7. Can''t really articulate what it is that I like about it, but I''m definitely drawn to the street on the right. It seems to quiet and deserted, though it looks like a place you wouldn''t want to be late at night. It''s also very crisp for a long exposure and the darkness doesn''t bother me. It feels balanced to me.', '2005-08-06 00:59:19.000000', NULL, 1),
(1589955, 211800, 17279, '<td valign="top">I don''t think the long exposure here adds a whole lot.  The subject seems to be the man sitting on the bench, and the vaguely present light trail doesn''t add as much as perhaps a more visible but slightly blurred car.</td>', 'I don''t think the long exposure here adds a whole lot.  The subject seems to be the man sitting on the bench, and the vaguely present light trail doesn''t add as much as perhaps a more visible but slightly blurred car.', '2005-08-06 01:02:03.000000', NULL, 1),
