(1677969, 210425, 31403, '<td valign="top">you are a great photographer, I really like your stuff, and I''m just too shy to say it I guess!  :-)<br/> <br/>This is very cool, you have good reason to be proud of it.</td>', 'you are a great photographer, I really like your stuff, and I''m just too shy to say it I guess!  :-) This is very cool, you have good reason to be proud of it.', '2005-09-06 03:09:44.000000', NULL, 0),
(1684925, 210821, 38267, '<td valign="top">This is my favorite of all your pictures.  I love the moss and the silvery look to the water.  Great composition and great job of really creating a beautiful image.</td>', 'This is my favorite of all your pictures.  I love the moss and the silvery look to the water.  Great composition and great job of really creating a beautiful image.', '2005-09-07 22:59:33.000000', NULL, 0),
(1690583, 210821, 12750, '<td valign="top">This is awesome, very surreal with such a long exposure. My type of feel!  Well done!</td>', 'This is awesome, very surreal with such a long exposure. My type of feel!  Well done!', '2005-09-09 15:04:55.000000', NULL, 0),
(1695598, 210821, 37719, '<td valign="top">This is an awesome shot.  I love the ''feel'' of the whole image.  The long exposure makes it work.  The colors are great.  The texture is excellent. Very well done.</td>', 'This is an awesome shot.  I love the ''feel'' of the whole image.  The long exposure makes it work.  The colors are great.  The texture is excellent. Very well done.', '2005-09-11 18:21:35.000000', NULL, 0),
